import sys
from collections import Counter

import h5py
import numpy as np


def as_text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, np.bytes_):
        return bytes(value).decode("utf-8", errors="replace")
    return str(value)


def read_node(node):
    if isinstance(node, h5py.Dataset):
        data = node[()]
        if getattr(data, "shape", ()) == ():
            return np.array([data])
        return np.asarray(data)

    encoding = as_text(node.attrs.get("encoding-type", ""))
    if encoding == "categorical" or ("codes" in node and "categories" in node):
        codes = np.asarray(node["codes"][()])
        categories = [as_text(x) for x in np.asarray(node["categories"][()])]
        values = []
        for code in codes:
            code_int = int(code)
            values.append(categories[code_int] if code_int >= 0 else "")
        return np.asarray(values, dtype=object)

    if "values" in node:
        return read_node(node["values"])

    raise TypeError(f"unsupported H5AD obs node: {node.name}")


def read_obs(path):
    with h5py.File(path, "r") as handle:
        obs = handle["obs"]
        col_order = obs.attrs.get("column-order")
        if col_order is None:
            columns = [key for key in obs.keys() if key != "_index"]
        else:
            columns = [as_text(x) for x in col_order]
        data = {}
        for column in columns:
            data[column] = read_node(obs[column])
        n_obs = len(next(iter(data.values()))) if data else len(read_node(obs["_index"]))
    return n_obs, columns, data


def main():
    input_path, output_path = sys.argv[1], sys.argv[2]
    n_obs, columns, data = read_obs(input_path)
    target_samples = {"Patient_005", "Patient_006", "Patient_007", "Patient_018", "Patient_040"}

    with open(output_path, "w", encoding="utf-8") as out:
        out.write(f"n_obs\t{n_obs}\n")
        out.write("columns\t" + "\t".join(columns) + "\n")
        out.write("column\tunique_count\ttop_values\n")
        for column in columns:
            values = [as_text(x) for x in data[column]]
            counts = Counter(values)
            top = "; ".join(f"{k}:{v}" for k, v in counts.most_common(25))
            out.write(f"{column}\t{len(counts)}\t{top}\n")

        out.write("\ncolumns_containing_target_patient_ids\n")
        for column in columns:
            values = [as_text(x) for x in data[column]]
            hits = sorted(target_samples.intersection(values))
            if hits:
                out.write(f"{column}\t{','.join(hits)}\n")


if __name__ == "__main__":
    main()

