import sys

import h5py
import numpy as np


def as_text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, np.bytes_):
        return bytes(value).decode("utf-8", errors="replace")
    return str(value)


def format_attr(value):
    if isinstance(value, np.ndarray):
        if value.size <= 12:
            return "[" + ",".join(as_text(x) for x in value.ravel()) + "]"
        return f"array(shape={value.shape}, dtype={value.dtype})"
    return as_text(value)


def visit(name, obj, out, max_items=20):
    attrs = ";".join(f"{key}={format_attr(value)}" for key, value in obj.attrs.items())
    if isinstance(obj, h5py.Dataset):
        preview = ""
        if obj.size and obj.size <= max_items and len(obj.shape) <= 1:
            preview = ";preview=" + ",".join(as_text(x) for x in obj[()])
        out.write(f"DATASET\t/{name}\tshape={obj.shape}\tdtype={obj.dtype}\tattrs={attrs}{preview}\n")
    else:
        keys = list(obj.keys())
        key_text = ",".join(keys[:max_items])
        if len(keys) > max_items:
            key_text += f",...(+{len(keys) - max_items})"
        out.write(f"GROUP\t/{name}\tn_children={len(keys)}\tkeys={key_text}\tattrs={attrs}\n")


def main():
    input_path, output_path = sys.argv[1], sys.argv[2]
    with h5py.File(input_path, "r") as handle, open(output_path, "w", encoding="utf-8") as out:
        out.write("root_keys\t" + ",".join(handle.keys()) + "\n")
        out.write("root_attrs\t" + ";".join(f"{k}={format_attr(v)}" for k, v in handle.attrs.items()) + "\n")
        handle.visititems(lambda name, obj: visit(name, obj, out))


if __name__ == "__main__":
    main()

