import csv
import math
import sys
from collections import Counter, defaultdict

import h5py
import numpy as np


def as_text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, np.bytes_):
        return bytes(value).decode("utf-8", errors="replace")
    return str(value)


def read_h5ad_obs(path):
    with h5py.File(path, "r") as handle:
        obs = handle["obs"]
        cell_ids = [as_text(x) for x in obs["_index"][()]]
        sample_node = obs["sampleID"]
        categories = [as_text(x) for x in sample_node["categories"][()]]
        codes = np.asarray(sample_node["codes"][()])
        sample_ids = [categories[int(code)] for code in codes]
    if len(cell_ids) != len(sample_ids):
        raise SystemExit("H5AD obs index/sampleID length mismatch")
    return list(zip(cell_ids, sample_ids))


def main():
    h5ad_path, meta_path, output_path = sys.argv[1:4]
    candidate_patients = {
        "Patient_005", "Patient_006", "Patient_007", "Patient_018", "Patient_040"
    }
    immune_types = {"B", "CD4", "CD8", "DC", "Gran", "Mast", "Mo", "NK", "Tregs"}

    obs_cells = defaultdict(list)
    for cell_id, patient in read_h5ad_obs(h5ad_path):
        prefix = patient + "_"
        if not cell_id.startswith(prefix):
            raise SystemExit(f"Invalid H5AD cell ID/patient pairing: {cell_id} / {patient}")
        obs_cells[patient].append(cell_id[len(prefix):])

    meta_by_sample = defaultdict(dict)
    sample_info = {}
    with open(meta_path, newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        required = {"SampleID", "Tissue", "Cells", "PatientID", "Disease", "CellName"}
        if not required.issubset(reader.fieldnames or []):
            raise SystemExit(f"Missing metadata fields; got {reader.fieldnames!r}")
        for row in reader:
            sample = row["SampleID"]
            cell_id = row["Cells"]
            prefix = sample + "_"
            if not cell_id.startswith(prefix):
                raise SystemExit(f"Invalid source cell ID: {cell_id}")
            barcode = cell_id[len(prefix):]
            if barcode in meta_by_sample[sample]:
                raise SystemExit(f"Duplicate barcode within source sample: {sample}/{barcode}")
            meta_by_sample[sample][barcode] = row
            sample_info[sample] = (row["Tissue"], row["PatientID"], row["Disease"])

    patient_to_sample = {}
    barcode_diagnostics = []
    for patient, barcode_list in sorted(obs_cells.items()):
        barcode_set = set(barcode_list)
        if len(barcode_set) != len(barcode_list):
            raise SystemExit(f"Duplicate barcode within H5AD patient: {patient}")
        exact = [
            sample for sample, rows in meta_by_sample.items()
            if len(rows) == len(barcode_set) and set(rows) == barcode_set
        ]
        if len(exact) != 1:
            top = sorted(
                (
                    (len(barcode_set.intersection(rows)), sample, len(rows))
                    for sample, rows in meta_by_sample.items()
                ),
                reverse=True,
            )[:5]
            raise SystemExit(f"Expected one exact source match for {patient}, got {exact}; top={top}")
        sample = exact[0]
        patient_to_sample[patient] = sample
        tissue, source_patient, disease = sample_info[sample]
        barcode_diagnostics.append(
            (patient, sample, len(barcode_set), tissue, source_patient, disease)
        )

    joined = []
    patient_cell_types = defaultdict(Counter)
    patient_disease = {}
    for patient, barcode_list in obs_cells.items():
        sample = patient_to_sample[patient]
        disease_values = set()
        for barcode in barcode_list:
            row = meta_by_sample[sample][barcode]
            joined.append((patient, row))
            patient_cell_types[patient][row["CellName"]] += 1
            disease_values.add(row["Disease"])
        if len(disease_values) != 1:
            raise SystemExit(f"Multiple disease labels for {patient}: {disease_values}")
        disease = next(iter(disease_values))
        if disease not in {"LUAD", "LUSC"}:
            raise SystemExit(f"Unexpected disease for {patient}: {disease}")
        patient_disease[patient] = disease

    candidate_rows = []
    for patient in sorted(candidate_patients):
        total = len(obs_cells[patient])
        dc = patient_cell_types[patient]["DC"]
        candidate_rows.append((patient, patient_disease[patient], dc, total, dc / total))

    lusc_candidates = [row for row in candidate_rows if row[1] == "LUSC"]
    if not lusc_candidates:
        raise SystemExit("No LUSC candidate samples")
    winner = max(lusc_candidates, key=lambda row: (row[4], row[0]))

    nonimmune_total = 0
    lusc_basal = 0
    for patient, row in joined:
        cell_type = row["CellName"]
        if cell_type not in immune_types:
            nonimmune_total += 1
        if patient_disease[patient] == "LUSC" and cell_type == "Basal":
            lusc_basal += 1

    percentage = 100.0 * lusc_basal / nonimmune_total
    rounded_to_20 = int(math.floor((percentage + 10.0) / 20.0) * 20)

    with open(output_path, "w", encoding="utf-8", newline="") as out:
        out.write("VALIDATION\n")
        out.write(f"obs_cells\t{sum(len(v) for v in obs_cells.values())}\n")
        out.write(f"metadata_cells\t{sum(len(v) for v in meta_by_sample.values())}\n")
        out.write(f"joined_cells\t{len(joined)}\n")
        out.write(f"exact_patient_sample_matches\t{len(patient_to_sample)}\n")
        out.write("MATCHED_SAMPLES\n")
        out.write("patient\tsource_sample\tcells\ttissue\tsource_patient\tdisease\n")
        for row in barcode_diagnostics:
            out.write("\t".join(map(str, row)) + "\n")
        out.write("CANDIDATES\n")
        out.write("patient\tdisease\tdc_cells\tall_cells\tdc_fraction\n")
        for patient, disease, dc, total, fraction in candidate_rows:
            out.write(f"{patient}\t{disease}\t{dc}\t{total}\t{fraction:.12f}\n")
        out.write("NONIMMUNE_CALCULATION\n")
        out.write(f"lusc_basal_cells\t{lusc_basal}\n")
        out.write(f"all_nonimmune_cells\t{nonimmune_total}\n")
        out.write(f"percentage\t{percentage:.12f}\n")
        out.write(f"nearest_20_percent\t{rounded_to_20}\n")
        out.write("FINAL_ANSWER\n")
        out.write(f"{winner[0]};{rounded_to_20}\n")


if __name__ == "__main__":
    main()

